-- oracle: pub400
-- A 7.5 shop's personnel tables: FOR SYSTEM NAME, CREATE OR REPLACE TABLE, BOOLEAN and TIMESTAMP(0) columns, TRUNCATE.
CREATE TABLE {lib}.D4_DEPARTMENT_MASTER FOR SYSTEM NAME D4DEPTM (DEPARTMENT_CODE CHAR(4) NOT NULL PRIMARY KEY, DEPARTMENT_NAME VARCHAR(40) NOT NULL, IS_ACTIVE BOOLEAN NOT NULL DEFAULT TRUE, OPENED_AT TIMESTAMP(0) NOT NULL DEFAULT CURRENT TIMESTAMP);
INSERT INTO {lib}.D4_DEPARTMENT_MASTER (DEPARTMENT_CODE, DEPARTMENT_NAME, OPENED_AT) VALUES ('ACCT', 'Accounting', '2020-01-01-08.00.00'), ('SHIP', 'Shipping', '2021-06-15-07.30.00');
INSERT INTO {lib}.D4_DEPARTMENT_MASTER VALUES ('OLD1', 'Closed', FALSE, '2001-01-01-00.00.00');
SELECT DEPARTMENT_CODE, DEPARTMENT_NAME, IS_ACTIVE, OPENED_AT FROM {lib}.D4_DEPARTMENT_MASTER ORDER BY DEPARTMENT_CODE;
SELECT DEPARTMENT_CODE FROM {lib}.D4_DEPARTMENT_MASTER WHERE IS_ACTIVE ORDER BY 1;
SELECT DEPARTMENT_CODE FROM {lib}.D4_DEPARTMENT_MASTER WHERE NOT IS_ACTIVE;
SELECT TABLE_NAME, SYSTEM_TABLE_NAME FROM QSYS2.SYSTABLES WHERE TABLE_SCHEMA = '{lib}' AND TABLE_NAME = 'D4_DEPARTMENT_MASTER';
CREATE OR REPLACE TABLE {lib}.D4_DEPARTMENT_MASTER FOR SYSTEM NAME D4DEPTM (DEPARTMENT_CODE CHAR(4) NOT NULL PRIMARY KEY, DEPARTMENT_NAME VARCHAR(60) NOT NULL, IS_ACTIVE BOOLEAN NOT NULL DEFAULT TRUE, OPENED_AT TIMESTAMP(0) NOT NULL DEFAULT CURRENT TIMESTAMP, COST_CENTER CHAR(6)) ON REPLACE PRESERVE ROWS;
SELECT DEPARTMENT_CODE, DEPARTMENT_NAME, COST_CENTER FROM {lib}.D4_DEPARTMENT_MASTER ORDER BY DEPARTMENT_CODE;
TRUNCATE TABLE {lib}.D4_DEPARTMENT_MASTER IMMEDIATE;
SELECT COUNT(*) FROM {lib}.D4_DEPARTMENT_MASTER;
TRUNCATE {lib}.D4_DEPARTMENT_MASTER;
CREATE OR REPLACE TABLE {lib}.D4_DEPARTMENT_MASTER (DEPARTMENT_CODE CHAR(4) NOT NULL) ON REPLACE DELETE ROWS;
SELECT COLUMN_NAME FROM QSYS2.SYSCOLUMNS WHERE TABLE_SCHEMA = '{lib}' AND TABLE_NAME = 'D4_DEPARTMENT_MASTER' ORDER BY ORDINAL_POSITION;
DROP TABLE {lib}.D4_DEPARTMENT_MASTER;
